class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        if monthly_limit_mib < 0:
            raise ValueError("Monthly limit cannot be negative.")
        self.limit_bytes: float = monthly_limit_mib * 1024 * 1024
        # Maps month -> {filename: size_bytes}
        self._months: dict[str, dict[str, int]] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like '2026-01'."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0.")

        files = self._months.setdefault(month, {})

        # If already uploaded in the same month, it does not count towards the limit a second time
        if name in files:
            return

        current_used = sum(files.values())
        if current_used + size_bytes > self.limit_bytes:
            raise ValueError("Upload exceeds the monthly quota limit.")

        files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        if month in self._months and name in self._months[month]:
            del self._months[month][name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        if month not in self._months:
            return 0
        return sum(self._months[month].values())
